import{_ as s,l as i,o as e,c as l,v as r,p as n,x as t,d as A,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"ARP 缓存与代理","description":"","frontmatter":{"title":"ARP 缓存与代理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/arp-cache.md","filePath":"cs/arp-cache.md","lastUpdated":1789023840000}'),c={name:"cs/arp-cache.md"};function h(P,a,_,E,u,m){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="arp-缓存与代理" tabindex="-1">ARP 缓存与代理 <a class="header-anchor" href="#arp-缓存与代理" aria-label="Permalink to &quot;ARP 缓存与代理&quot;">​</a></h1><div class="epigraph"><p>解析结果必须缓存才扛得住广播；超时与代理改变的是表项从哪来，不是 IP 到 MAC 的那道翻译。</p><footer>—— 据 Plummer, RFC 826；Kurose and Ross 对 ARP 表与代理 ARP 的整理</footer></div><p><a href="/cs/arp">上一课</a>给出同一链路上的 IP→MAC：广播问、单播答。本课不重写请求格式。缺口是表：每包都广播会淹没<a href="/cs/vlan">VLAN</a> 里的广播域；表项过期或被他人改写，下一跳会发错人。代理 ARP 则让路由器替一整段地址回答。本课不把子网掩码写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ARP 成功一次之后，后续帧应直接封装。缓存：IP 映射到 MAC，带生存时间。无超时则主机搬家后流量仍打到旧口；过短则广播风暴。Gratuitous ARP 用于宣告与冲突检测。代理：路由器对「不在本机但可达」的 IP 回答自己的 MAC，把本应跨网的包先拉过来再路由——曾用来把主机从子网细节里藏起来。缺口是<strong>表的维护合同</strong>，不是新的帧类型。</p><p><span class="marginnote">缓存没有认证。后到的应答可以覆盖表项。防御是信任边界：只在链路上使用 ARP、静态表用于关键网关、后课用 NDP 与安全扩展对照，而不是在本课写攻击步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送路径：查缓存；未命中则排队并广播请求，填表后再封装。收应答：更新或插入，刷新计时。代理 ARP 在路由器开启时，对特定前缀代答；今日默认少用，因为和 CIDR 边界纠缠、排障困难。交换机仍把 ARP 请求当广播；缓存命中之后的单播帧才走 MAC 表。</p>',8)),(e(),n(p,null,{default:t(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OUT%5B%22%E5%BE%85%E5%8F%91%20IP%20%E5%8C%85%22%5D%20--%3E%20TAB%5B%22%E6%9F%A5%20ARP%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20TAB%20--%3E%20HIT%5B%22%E5%B0%81%E8%A3%85%E5%B9%B6%E5%8F%91%E9%80%81%22%5D%0A%20%20TAB%20--%3E%20MISS%5B%22%E5%B9%BF%E6%92%AD%E8%AF%B7%E6%B1%82%E5%B9%B6%E6%8E%92%E9%98%9F%22%5D%0A%20%20PROXY%5B%22%E4%BB%A3%E7%90%86%E5%BA%94%E7%AD%94%22%5D%20--%3E%20TAB%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缓存把一跳翻译从控制平面（广播）变成数据平面（查表），让 <a href="/cs/io-dma">DMA</a> 出去的帧不必每次泛洪。代理把「是否同一链路」从主机判断部分上收到路由器，模糊了后课子网的边界——这正是下一课必须钉掩码的原因。端到端仍不在 ARP：表填对只保证这一跳 MAC 对。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 NDP 选项清单，不把 ARP 探测当安全协议。静态 ARP 是运维钉死网关，不是密码学绑定。哪些地址算同一链路、要不要问网关，下一课 <a href="/cs/ip-subnet">IP 编址与子网</a>。</p><p>后课默认：同一链路上翻译结果会缓存并过期。没有掩码，就还不知道该问目的还是问默认网关。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ARP 表有超时；命中后不再广播。</li><li>代理 ARP 让路由器代答，模糊直连边界。</li><li>子网决定问谁，下一课。</li><li>出处：RFC 826；Kurose and Ross。</li></ul>',7))])}const f=s(c,[["render",h]]);export{R as __pageData,f as default};
